// Jarvis Hologram (boy). One look only: a living, breathing hologram boy made from your picture,
// plus a glass message/alert window you control with swipes. Draws behind the app and reads its state + voice level.
(() => {
  "use strict";
  if (window.Skin) return;
  const BOY = "data:image/webp;base64,";

  // ---- sprite facts (pixels inside the boy picture, 850 x 898) ----
  const SW = 850, SH = 898, NECK = { x: 470, y: 440 };
  const MOUTH = { x: 283, y: 346 }, EYE = { x: 335, y: 242 }, CHEEK = { x: 352, y: 268 };

    const $ = s => document.querySelector(s);
  const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches, RM = reduced ? .4 : 1;
  const t0 = Date.now();

  // ---- canvas behind the app ----
  const cv = document.createElement("canvas");
  cv.id = "skin"; cv.style.cssText = "position:fixed;inset:0;width:100%;height:100%;z-index:-1;pointer-events:none";
  document.body.prepend(cv);
  const g = cv.getContext("2d");
  let W = 0, H = 0, dpr = 1;
  const fig = document.createElement("canvas"), fg = fig.getContext("2d");
  let ks = 1;
  function size() {
    dpr = Math.min(2, devicePixelRatio || 1); W = innerWidth; H = innerHeight;
    cv.width = W * dpr; cv.height = H * dpr; g.setTransform(dpr, 0, 0, dpr, 0, 0);
    ks = Math.max(.35, Math.min(1, Math.min(W * .98 / SW, H * .62 / SH) * dpr));
    fig.width = Math.ceil((SW + 40) * ks); fig.height = Math.ceil((SH + 40) * ks);
  }
  addEventListener("resize", size); size();

  // ---- the boy picture ----
  const img = new Image(); let ready = false, lid = "rgb(40,70,200)";
  img.onload = () => {
    ready = true;
    try {   // skin colour for eyelids, and a small face for the avatar circles
      const c = document.createElement("canvas"); c.width = c.height = 96; const x = c.getContext("2d", { willReadFrequently: true });
      x.drawImage(img, 190, 60, 280, 280, 0, 0, 96, 96);
      document.documentElement.style.setProperty("--face", "url(" + c.toDataURL("image/png") + ")");
      const d = document.createElement("canvas"); d.width = d.height = 8; const y = d.getContext("2d", { willReadFrequently: true });
      y.drawImage(img, CHEEK.x - 4, CHEEK.y - 4, 8, 8, 0, 0, 8, 8);
      const p = y.getImageData(0, 0, 8, 8).data; let r = 0, gg = 0, b = 0, n = 0;
      for (let i = 0; i < p.length; i += 4) if (p[i + 3] > 200) { r += p[i]; gg += p[i + 1]; b += p[i + 2]; n++; }
      if (n) lid = `rgb(${r / n | 0},${gg / n | 0},${b / n | 0})`;
    } catch (e) {}
  };
  img.src = BOY;

  // ---- styles ----
  const css = document.createElement("style");
  css.textContent = `
body.sk .av{background:#06142a var(--face,none) center/cover no-repeat!important;border:1.5px solid #5fd6ff;box-shadow:0 0 12px #1f7bffaa}
body.sk .hudring{display:none}
body.sk .core{position:relative}
body.sk .ringbox{display:flex;align-items:flex-end;justify-content:center;max-height:none;max-width:none;width:100%;height:100%;aspect-ratio:auto}
body.sk .ringbox .orbw{position:relative;inset:auto;width:66px;margin-bottom:2px;z-index:3}
body.sk .orb{background:radial-gradient(circle,#0d3a78,#04122a);border:2px solid #5fd6ff;box-shadow:0 0 24px -2px #1b9bff,inset 0 0 14px #1b7dff88}
body.sk .orb i{display:none}
body.sk .orb::after{content:none}
body.sk .orb svg{display:block;position:absolute;inset:0;margin:auto;width:34%;height:34%;z-index:2;fill:none;stroke:#cfefff;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}`
  document.head.append(css);

  // ---- helpers ----
  const stateNow = () => document.body.dataset.s || "idle";
  const lvl = () => parseFloat(getComputedStyle(document.body).getPropertyValue("--l")) || 0;
  const col = (hue, a = 1, l = 60) => `hsla(${hue},100%,${l}%,${a})`;
  const sm = (a, b, v) => { const t = Math.min(1, Math.max(0, (v - a) / (b - a))); return t * t * (3 - 2 * t); };
  const rnd = (a, b) => a + Math.random() * (b - a);
  let L = 0;
  function stateHue() { const s = stateNow(); return s === "think" ? 275 : s === "listen" ? 178 : s === "speak" ? 200 : 210; }

  function platform(cx, y, w, hue, t) {
    for (let i = 0; i < 4; i++) {
      const k = 1 - i * .2 + Math.sin(t * 2 + i) * .02;
      g.strokeStyle = col(hue, .85 - i * .15, 62); g.lineWidth = 1.5;
      g.shadowColor = col(hue, 1); g.shadowBlur = 14;
      g.beginPath(); g.ellipse(cx, y, w * k, w * k * .16, 0, 0, 7); g.stroke();
    }
    g.shadowBlur = 0;
  }
  const parts = Array.from({ length: 45 }, () => ({ x: Math.random(), y: Math.random(), s: .02 + Math.random() * .06 }));
  function motes(hue, dt) {
    for (const p of parts) { p.y -= p.s * dt; if (p.y < 0) { p.y = 1; p.x = Math.random(); }
      g.fillStyle = col(hue, .55 * p.y, 75); g.fillRect(p.x * W, p.y * H, 1.6, 1.6); }
  }
  function backdrop(hue) {
    const gr = g.createRadialGradient(W / 2, H * 1.05, 10, W / 2, H * 1.05, H * .9);
    gr.addColorStop(0, col(hue, .35, 30)); gr.addColorStop(1, "#02050d"); g.fillStyle = gr; g.fillRect(0, 0, W, H);
    g.strokeStyle = col(hue, .06, 60); g.lineWidth = 1;
    for (let i = 0; i < 12; i++) { const y = H * .62 + (H * .38) * Math.pow(i / 12, 2); g.beginPath(); g.moveTo(0, y); g.lineTo(W, y); g.stroke(); }
  }

  // ---- the living boy ----
  // pose: head follows the voice, the body breathes, eyes blink. Rows of the picture are bent so nothing tears.
  const P = { tx: 0, ty: 0, th: 0, sq: 0, sway: 0 };
  const wHead = y => sm(520, 380, y);
  const mapX = (x, y) => x + wHead(y) * (P.tx + (NECK.y - y) * P.th);
  const mapY = y => y + wHead(y) * (P.ty + (y - NECK.y) * P.sq);
  let breathPh = 0, B = 0, sighT = -99, nextSigh = 9, Ls = 0, Lp = 0, beat = 0, blinkAt = -1, nextBlink = 2, glitchAt = -9, nextGlitch = 7;
  const lerpTo = (k, v, dt, r = 8) => k + (v - k) * (1 - Math.exp(-dt * r));

  function pose(t, dt) {
    const s = stateNow(), spk = s === "speak", lis = s === "listen", thk = s === "think";
    // breathing (a little faster while talking) plus a slow deep sigh now and then
    breathPh += dt * (spk ? .32 : lis ? .26 : .22) * Math.PI * 2;
    let b = .5 - .5 * Math.cos(breathPh);
    if (t > nextSigh) { sighT = t; nextSigh = t + rnd(14, 24); }
    const se = t - sighT; if (se >= 0 && se < 2.6) b = Math.min(1.5, b + .5 * Math.sin(Math.PI * se / 2.6));
    B = b;
    // mouth + head beats follow the real voice level
    const open = Math.min(1, L * 1.7);
    Ls += (open - Ls) * (open > Ls ? .6 : .25);
    beat = Math.max(beat * .9, Math.max(0, Ls - Lp) * 3); Lp = Ls;
    const ty = (-1.5 + Math.sin(t * .9) * 1.4) * RM + (spk ? beat * 7 + Ls * 3 : 0) + (lis ? -Ls * 2.5 : 0);
    const th = (Math.sin(t * .55) * .012 + Math.sin(t * .23 + 1) * .01) * RM + (thk ? .03 : 0) + (spk ? Math.sin(t * 2.3) * .012 + Math.sin(t * 7.1) * .012 * Ls : 0) + (lis ? .018 + Math.sin(t * 1.7) * .006 : 0);
    const tx = Math.sin(t * .4) * 3 * RM + (lis ? -6 : 0) + (spk ? Math.sin(t * 1.9) * 2.5 : 0);
    const sq = (spk ? -Ls * .012 : 0) + (lis ? .006 : 0) + (thk ? -.008 : 0);
    P.tx = lerpTo(P.tx, tx, dt); P.ty = lerpTo(P.ty, ty, dt, 12); P.th = lerpTo(P.th, th, dt, 6); P.sq = lerpTo(P.sq, sq, dt, 8);
    P.sway = Math.sin(t * .35) * .004 * RM;
    // blink every few seconds, sometimes twice
    if (blinkAt < 0 && t > nextBlink) { blinkAt = t; }
    if (blinkAt >= 0 && t - blinkAt > .17) { const dbl = Math.random() < .2; blinkAt = -1; nextBlink = t + (dbl ? .25 : rnd(2.4, 5.8)); }
    if (!reduced && t > nextGlitch) { glitchAt = t; nextGlitch = t + rnd(6, 13); }
  }

  function drawStrips(f) {
    const step = 9;
    for (let sy = 0; sy < SH; sy += step) {
      const y0 = mapY(sy), y1 = mapY(Math.min(SH, sy + step)), dx = mapX(0, sy + step / 2) - 0;
      f.drawImage(img, 0, sy, SW, Math.min(step, SH - sy), dx, y0, SW, (y1 - y0) + .8);
    }
  }
  function drawFace(f, t) {
    // eyelid blink on the eye you can see
    if (blinkAt >= 0) {
      const p = (t - blinkAt) / .17, bl = p < .5 ? p * 2 : (1 - p) * 2, ex = mapX(EYE.x, EYE.y), ey = mapY(EYE.y);
      if (bl > .05) {
        f.fillStyle = lid; f.beginPath(); f.ellipse(ex, ey + 1, 27, 4 + 9 * bl, -.12, 0, 7); f.fill();
        f.strokeStyle = "rgba(4,10,50,.85)"; f.lineWidth = 2.2; f.beginPath(); f.ellipse(ex, ey - 4 + 12 * bl, 24, 4 * bl + .5, -.12, 0, Math.PI); f.stroke();
      }
    }
    // mouth opens with the voice
    if (Ls > .06) {
      const mx = mapX(MOUTH.x, MOUTH.y), my = mapY(MOUTH.y), ry = 1.5 + Ls * 10, rx = 19 + Ls * 4;
      f.save(); f.translate(mx, my + ry * .9); f.rotate(-.12);
      f.fillStyle = "rgba(3,8,40,.93)"; f.beginPath(); f.ellipse(0, 0, rx, ry, 0, 0, 7); f.fill();
      if (Ls > .35) { f.fillStyle = "rgba(110,130,255,.45)"; f.beginPath(); f.ellipse(0, ry * .45, rx * .55, ry * .38, 0, 0, 7); f.fill(); }
      f.strokeStyle = "rgba(150,175,255,.85)"; f.lineWidth = 3; f.beginPath(); f.ellipse(0, 0, rx, ry, 0, .15, Math.PI - .15); f.stroke();
      f.restore();
    }
  }
  function renderFig(t) {
    const f = fg; f.setTransform(1, 0, 0, 1, 0, 0); f.clearRect(0, 0, fig.width, fig.height);
    f.setTransform(ks, 0, 0, ks, 20 * ks, 20 * ks); f.imageSmoothingQuality = "high";
    f.save();
    f.translate(SW / 2, SH); f.rotate(P.sway); f.scale(1 + .007 * B, 1 + .010 * B); f.translate(-SW / 2, -SH);
    drawStrips(f); drawFace(f, t);
    f.restore();
    // hologram finish, only on the boy: scan lines, a moving light band, and a soft shimmer
    f.setTransform(1, 0, 0, 1, 0, 0); f.globalCompositeOperation = "source-atop";
    f.fillStyle = "rgba(2,8,30,.16)"; for (let y = 0; y < fig.height; y += 3) f.fillRect(0, y, fig.width, 1);
    const by = (((t * .16) % 1.3) - .15) * SH * ks + 20 * ks, bh = 46 * ks;
    const sw = f.createLinearGradient(0, by - bh, 0, by + bh); sw.addColorStop(0, "rgba(120,220,255,0)"); sw.addColorStop(.5, "rgba(140,230,255,.28)"); sw.addColorStop(1, "rgba(120,220,255,0)");
    f.fillStyle = sw; f.fillRect(0, by - bh, fig.width, bh * 2);
    f.globalCompositeOperation = "source-over";
  }

  function drawHolo(t, dt) {
    const hue = stateHue();
    // the boy lives in the middle block of the screen (where the ring used to be)
    pose.n = (pose.n || 0) + 1; if (!pose.cr || pose.n % 5 === 0) { const core = $(".core"); pose.cr = core ? core.getBoundingClientRect() : { top: 80, bottom: H * .6 }; }
    const cr = pose.cr, top = cr.top + 2, bottom = cr.bottom - 2;
    const target = Math.min(Math.max(150, bottom - top) / SH, W * .98 / SW);
    pose.k = pose.k ? pose.k + (target - pose.k) * .18 : target; const k = pose.k;
    const cx = W / 2, base = Math.max(top + 150, bottom);
    // glow + beam + platform
    const ay = base - SH * k * .55, ag = g.createRadialGradient(cx, ay, 10, cx, ay, SH * k * .75);
    ag.addColorStop(0, col(hue, .3 + L * .25, 45)); ag.addColorStop(1, "transparent"); g.fillStyle = ag; g.fillRect(0, 0, W, H);
    const bw = SW * k;
    const bm = g.createLinearGradient(0, base - SH * k, 0, base); bm.addColorStop(0, "transparent"); bm.addColorStop(1, col(hue, .14, 60));
    g.fillStyle = bm; g.beginPath(); g.moveTo(cx - bw * .28, base - SH * k); g.lineTo(cx + bw * .28, base - SH * k); g.lineTo(cx + bw * .5, base); g.lineTo(cx - bw * .5, base); g.fill();
    platform(cx, base - 2, bw * .52, hue, t);
    if (ready) {
      pose(t, dt); renderFig(t);
      const fl = reduced ? 1 : (Math.random() < .012 ? .8 : .97 + Math.sin(t * 31) * .03);
      const dx = cx - (SW / 2 + 20) * k, dy = base - (SH + 20) * k, dw = (SW + 40) * k, dh = (SH + 40) * k;
      g.globalAlpha = fl; g.drawImage(fig, dx, dy, dw, dh);
      if (t - glitchAt < .14) {   // quick hologram glitch
        g.globalCompositeOperation = "lighter"; g.globalAlpha = .28;
        g.drawImage(fig, dx + 4, dy, dw, dh); g.drawImage(fig, dx - 4, dy, dw, dh);
        g.globalCompositeOperation = "source-over";
      }
      g.globalAlpha = 1;
    }
    motes(hue, dt);
  }

  // ---- loop ----
  let last = performance.now();
  function frame(now) {
    requestAnimationFrame(frame);
    if (document.hidden || now - last < 28) return;   // about 35 frames a second keeps the phone cool
    const dt = Math.min(.1, (now - last) / 1000); last = now; const t = (Date.now() - t0) / 1000;
    L += (lvl() - L) * .5;
    g.clearRect(0, 0, W, H);
    drawHolo(t, dt);
  }
  requestAnimationFrame(frame);

  function ui() {
    document.documentElement.classList.add("sk"); document.body.classList.add("sk");
  }
  document.readyState === "loading" ? document.addEventListener("DOMContentLoaded", ui) : ui();
  window.Skin = { set() {}, command() { return false; }, modes: ["hologram"] };
})();
